 function buildingMesh(data,roof=false){let previous=null;const buckets=Array.from({length:roof?1:4},()=>({positions:[],uvs:[],colors:[]}));for(let i=0;i<data.length;i+=9){const x=(data[i]+data[i+3]+data[i+6])/3,z=(data[i+2]+data[i+5]+data[i+8])/3;let b=previous&&contains(previous,x,z)?previous:(buildingCells.get(Math.floor(x/30)+','+Math.floor(z/30))||[]).find(b=>contains(b,x,z));previous=b;const bucket=buckets[roof?0:(b?.style||0)],paint=b?(roof?b.roofPaint:b.paint):new T.Color('#d5e2e6');const dx=data[i+3]-data[i],dz=data[i+5]-data[i+2],dx2=data[i+6]-data[i],dz2=data[i+8]-data[i+2];const tx=Math.abs(dx)+Math.abs(dz)>.01?dx:dx2,tz=Math.abs(dx)+Math.abs(dz)>.01?dz:dz2,length=Math.hypot(tx,tz)||1;for(let j=0;j<9;j+=3){const px=data[i+j],py=data[i+j+1],pz=data[i+j+2];bucket.positions.push(px,py,pz);bucket.uvs.push(roof?(px-roofImagery.minX)/(roofImagery.maxX-roofImagery.minX):(px*tx/length+pz*tz/length)/7,roof?(roofImagery.maxZ-pz)/(roofImagery.maxZ-roofImagery.minZ):1-(py-(b?b.ground-datum:0))/3.4);let shade=roof?1:T.MathUtils.lerp(.8,1,Math.min(1,Math.max(0,(py-(b?b.ground-datum:0))/1.8)));bucket.colors.push(paint.r*shade,paint.g*shade,paint.b*shade)}}for(let i=0;i<buckets.length;i++){const b=buckets[i];if(!b.positions.length)continue;const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(b.positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(b.uvs,2));g.setAttribute('color',new T.Float32BufferAttribute(b.colors,3));g.computeVertexNormals();const material=roof?new T.MeshBasicMaterial({map:aerialTexture,side:T.DoubleSide}):new T.MeshLambertMaterial({map:textures.walls[i],emissive:'#ffc987',emissiveMap:textures.windowMasks[i],emissiveIntensity:0,vertexColors:true,side:T.DoubleSide});if(roof)photoMaterials.push(material);else windowMaterials.push(material);scene.add(new T.Mesh(g,material))}}
