 for(let j=0;j<4;j++){const points=wallBatches[j],g=new T.BufferGeometry(),uv=[];for(let i=0;i<points.length;i+=3)uv.push((points[i]+points[i+2])/7,1-points[i+1]/3.4);g.setAttribute('position',new T.Float32BufferAttribute(points,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.computeVertexNormals();const material=new T.MeshLambertMaterial({map:textures.walls[j],color:paintPalette[j],side:T.DoubleSide,emissive:'#ffc987',emissiveMap:textures.windowMasks[j],emissiveIntensity:0});windowMaterials.push(material);scene.add(new T.Mesh(g,material))}
 const outerRoofGeometry=new T.BufferGeometry();outerRoofGeometry.setAttribute('position',new T.Float32BufferAttribute(roofBatch,3));outerRoofGeometry.setAttribute('uv',new T.Float32BufferAttribute(roofUV,2));outerRoofGeometry.computeVertexNormals();const outerRoofMaterial=new T.MeshBasicMaterial({map:wideTexture,side:T.DoubleSide});photoMaterials.push(outerRoofMaterial);scene.add(new T.Mesh(outerRoofGeometry,outerRoofMaterial));
